import { mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join, resolve } from "node:path";
import {
	CodemodAdapterId,
	createBuiltinCodemodCatalog,
} from "../packages/codemod/src/swap/index.ts";

const outputDirectory = resolve(import.meta.dirname, "../packages/codemod/tests/routes");
const generatedHeader =
	"// Generated by scripts/generate-adapter-route-specs.ts. Do not edit by hand.";
const enumMembers = new Map(
	Object.entries(CodemodAdapterId).map(([name, id]) => [id, name] as const),
);
const catalog = createBuiltinCodemodCatalog();

function identifier(id: string): string {
	const member = enumMembers.get(id);
	if (member === undefined) throw new Error(`missing CodemodAdapterId member for ${id}`);
	return `CodemodAdapterId.${member}`;
}

function fileName(source: string, target: string): string {
	return `${source}-to-${target}.test.ts`;
}

function sourceText(source: string, target: string): string {
	const sourceExpression = identifier(source);
	const targetExpression = identifier(target);
	return `${generatedHeader}
import { expect, test } from "vitest";
import { CodemodAdapterId } from "../../src/swap/index.ts";
import {
	createAdapterRouteSpec,
	expectExplicitResidualEvidence,
	routeEvidence,
} from "../route-spec-support.ts";

const route = createAdapterRouteSpec(${sourceExpression}, ${targetExpression});

test("${source} -> ${target}: statically migrates the happy path", () => {
	const result = route.run("happy");
	expect(result.converted).toBeGreaterThan(0);
	expect(result.skipped).toBe(0);
	expect(result.residuals).toEqual([]);
	expect(result.validations.every((validation) => validation.valid)).toBe(true);
	expectExplicitResidualEvidence(result);
	expect(routeEvidence(result)).toMatchInlineSnapshot();
});

test("${source} -> ${target}: reports edge semantics without silent loss", () => {
	const result = route.run("edge");
	expect(result.converted + result.skipped + result.residuals.length).toBeGreaterThan(0);
	expectExplicitResidualEvidence(result);
	expect(routeEvidence(result)).toMatchInlineSnapshot();
});

test("${source} -> ${target}: preserves malformed input and reports the boundary", () => {
	const result = route.run("malformed");
	expect(result.code).toContain("/* unfinished ${source} */");
	expectExplicitResidualEvidence(result);
	expect(routeEvidence(result)).toMatchInlineSnapshot();
});

`;
}

mkdirSync(outputDirectory, { recursive: true });
for (const entry of readdirSync(outputDirectory)) {
	if (!entry.endsWith(".test.ts")) continue;
	const path = join(outputDirectory, entry);
	if (readFileSync(path, "utf8").startsWith(generatedHeader)) {
		// Keep the directory reproducible when an adapter is removed from the registry.
		writeFileSync(path, "");
	}
}
for (const source of catalog.adapters)
	for (const target of catalog.adapters)
		if (source.id !== target.id)
			writeFileSync(
				join(outputDirectory, fileName(source.id, target.id)),
				sourceText(source.id, target.id),
			);

for (const entry of readdirSync(outputDirectory)) {
	if (entry.endsWith(".test.ts") && readFileSync(join(outputDirectory, entry), "utf8") === "")
		throw new Error(`stale generated route spec: ${entry}`);
}
console.log(
	`generated ${(catalog.adapters.length * (catalog.adapters.length - 1)).toString()} directional route specs`,
);
